INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 4, 'theory', 'Quiz: NULL and text');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 0, 'The query SELECT * FROM customers WHERE city <> ''Moscow'' did not return a customer with no city given. Why?', '["It is a SQLite bug", "NULL <> ''Moscow'' gives UNKNOWN, and WHERE lets through only TRUE", "Rows with NULL are deleted from the table", "You need to write != instead of <>"]', 1, 'A comparison with NULL gives UNKNOWN, and the row is discarded. To include such rows, write city <> ''Moscow'' OR city IS NULL, or city IS NOT ''Moscow''.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 1, 'What does COALESCE(NULL, NULL, ''none'', ''x'') return?', '["NULL", "''none''", "''x''", "An error"]', 1, 'COALESCE returns the first argument that is not NULL: that is ''none''.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 2, 'What is ''Anna, '' || NULL equal to?', '["''Anna, ''", "''Anna, NULL''", "NULL", "An empty string"]', 2, 'Concatenating a string with NULL gives NULL. To keep the label, wrap the value in COALESCE(city, '''').');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 3, 'What is NULLIF(x, 0) used for in a denominator?', '["To turn zero into NULL and avoid division by zero", "To replace NULL with zero", "To round a number", "To check that x is positive"]', 0, 'NULLIF(a, b) returns NULL if a equals b. Division by NULL gives NULL, not an error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 4, 4, 'How do you select customers with no city given?', '["WHERE city = NULL", "WHERE city = ''''", "WHERE city IS NULL", "WHERE city == 0"]', 2, 'A comparison = NULL always gives UNKNOWN, so the check is done with the IS NULL operator.');
